  ('__NODE__', 'Casabe Artesanal', 'Alimentacion', 'Gastronomia Artesanal', 'Panaderia', 'internal', 'unidad', 'Casabe artesanal de yuca amarga. Pan ancestral indigena: yuca rallada, prensada en sebucan, tostada en budare. Lote: 1.2 kg yuca -> 6 tortas de ~100g. Energia lote: yuca (3.6 MJ) + coccion 40 min (4 MJ) = 7.6 MJ. Por kg: 12.7 MJ/kg = 3.5 kWh/kg. Por unidad (100g): 1 TQ. Fuente: recetas tradicionales + LCA yuca. Documentado en Feria Conuquera (Flor de Tilo).', 'De Conuco', '', '', 1, 0, 'kg', 0, 2, 1, 1, 0, true, true, false);
INSERT INTO products (node_domain, name, parent_category, category, subcategory, origin, unit, description, badge, image_url, product_code, price_per_unit, price_per_kg, base_unit, weight_kg, energy_direct, energy_human, energy_inputs, energy_amortization, is_approved, is_system, is_composite) VALUES
  ('__NODE__', 'Catalinas Artesanales', 'Alimentacion', 'Gastronomia Artesanal', 'Dulces Tradicionales', 'internal', 'unidad', 'Catalinas (paledonias/cucas negras). Galletas dulces especiadas. Lote: 280g harina + 250g papelon + 100g mantequilla + 1 huevo -> 8 unidades de ~88g. Energia lote: 14.65 MJ. Por kg: 20.9 MJ/kg = 5.8 kWh/kg. Por unidad (88g): 1 TQ. Fuente: recetas tradicionales. Documentado en Feria Conuquera (Flor de Tilo).', 'De Conuco', '', '', 1, 0, 'kg', 0, 3, 1, 2, 0, true, true, false);
INSERT INTO products (node_domain, name, parent_category, category, subcategory, origin, unit, description, badge, image_url, product_code, price_per_unit, price_per_kg, base_unit, weight_kg, energy_direct, energy_human, energy_inputs, energy_amortization, is_approved, is_system, is_composite) VALUES
  ('__NODE__', 'Croquetas de Soya Artesanales', 'Alimentacion', 'Gastronomia Artesanal', 'Vegetariano', 'internal', 'unidad', 'Croquetas de soya artesanales. Lote: 200g soya + 50g harina -> 10 croquetas de ~25g. Energia lote: 5.7 MJ. Por kg: 22.8 MJ/kg = 6.3 kWh/kg. Por unidad (25g): 1 TQ. Fuente: Desde La Plaza. Documentado en Feria Conuquera (Luis Angel Leisiaga).', 'Vegetariano', '', '', 1, 0, 'kg', 0, 2, 1, 2, 0, true, true, false);
