  ('__NODE__', 'Dulces y Conservas Tradicionales', 'Alimentacion', 'Gastronomia Artesanal', 'Dulces Tradicionales', 'internal', 'kg', 'Dulce de lechosa, cabello de angel, jalea de guayaba, conservas de coco, bocadillo, encurtidos, salsas. Energia: 25-30 MJ/kg = 7-8 kWh/kg (cocccion + conservacion).', 'Plato Patrimonial', '/images/products/alimentacion/dulces-conservas.jpg', '', 8, 0, 'kg', 0, 8, 0, 0, 0, true, true, false);
