  ('__NODE__', 'Encurtidos y Salsas', 'Alimentacion', 'Gastronomia Artesanal', 'Conservas', 'internal', 'frasco', 'Encurtidos de vegetales, tomate enlatado, salsa picante, guasacaca, pesto. Energia: ~25 MJ/kg = 7 kWh/kg (cocccion + envasado).', 'Conserva Viva', '/images/products/alimentacion/encurtidos-salsas.jpg', '', 8, 0, 'kg', 0, 8, 0, 0, 0, true, true, false);
