  ('__NODE__', 'Harina Buen Pan', 'Alimentacion', 'Gastronomia Artesanal', 'Harinas Alternativas', 'internal', 'kg', 'Harina Buen Pan. Producto compuesto: harina de yuca, harina de cambur, harina de trigo. Energia calculada por componentes. Documentado en Feria Conuquera.', 'De Conuco', '', '', 0, 0, 'kg', 0, 0, 0, 0, 0, true, true, false);
