  ('__NODE__', 'Harina de Cambur Artesanal', 'Alimentacion', 'Gastronomia Artesanal', 'Harinas Alternativas', 'internal', 'kg', 'Harina de cambur artesanal. Lote: 5 kg cambur verde -> 1 kg harina (rendimiento 20%). Energia: cambur (9 MJ) + secado (2) + molienda (1) = 12 MJ/kg = 3.3 kWh/kg. Precio: 3 TQ/kg. Fuente: Desde La Plaza. Documentado en Feria Conuquera (Luis Angel Leisiaga).', 'De Conuco', '', '', 3, 0, 'kg', 0, 2, 1, 1, 0, true, true, false);
INSERT INTO products (node_domain, name, parent_category, category, subcategory, origin, unit, description, badge, image_url, product_code, price_per_unit, price_per_kg, base_unit, weight_kg, energy_direct, energy_human, energy_inputs, energy_amortization, is_approved, is_system, is_composite) VALUES
  ('__NODE__', 'Harina de Yuca Artesanal', 'Alimentacion', 'Gastronomia Artesanal', 'Harinas Alternativas', 'internal', 'kg', 'Harina de yuca artesanal. Lote: 2.5 kg yuca -> 1 kg harina (rendimiento 40%). Energia: yuca (7.5 MJ) + secado (3) + molienda (1) = 11.5 MJ/kg = 3.2 kWh/kg. Precio: 3 TQ/kg. Fuente: LCA cassava flour Nigeria, CIAT. Documentado en Feria Conuquera (Luis Angel Leisiaga).', 'De Conuco', '', '', 3, 0, 'kg', 0, 2, 1, 1, 0, true, true, false);
