  ('__NODE__', 'Lacteos Artesanales', 'Alimentacion', 'Gastronomia Artesanal', 'Lacteos', 'internal', 'kg', 'Queso fresco, de mano, guayanes, suero, cuajada, yogurt, mantequilla. Energia: 25-36 MJ/kg = 7-10 kWh/kg (10L leche/kg + fermentacion + frio). Fuente: Agribalyse.', 'Pastoreo Libre', '/images/products/alimentacion/lacteos-artesanales.jpg', '', 8, 0, 'kg', 0, 8, 0, 0, 0, true, true, false);
INSERT INTO products (node_domain, name, parent_category, category, subcategory, origin, unit, description, badge, image_url, product_code, price_per_unit, price_per_kg, base_unit, weight_kg, energy_direct, energy_human, energy_inputs, energy_amortization, is_approved, is_system, is_composite) VALUES
  ('__NODE__', 'Naiboa Artesanal', 'Alimentacion', 'Gastronomia Artesanal', 'Dulces Tradicionales', 'internal', 'unidad', 'Naiboa artesanal. Primer dulce netamente venezolano. Dos tortas de casabe rellenas con melado de papelon, queso blanco rallado y semillas de anis, horneadas. Lote: 2 casabe (200g) + 50g papelon + 30g queso -> 1 unidad 280g. Energia lote: 5.55 MJ. Por kg: 19.8 MJ/kg = 5.5 kWh/kg. Por unidad (280g): 2 TQ. Fuente: Wikipedia, EcuRed. Documentado en Feria Conuquera (Flor de Tilo).', 'De Conuco', '', '', 2, 0, 'kg', 0, 3, 1, 2, 0, true, true, false);
INSERT INTO products (node_domain, name, parent_category, category, subcategory, origin, unit, description, badge, image_url, product_code, price_per_unit, price_per_kg, base_unit, weight_kg, energy_direct, energy_human, energy_inputs, energy_amortization, is_approved, is_system, is_composite) VALUES
  ('__NODE__', 'Pan Artesanal de Masa Madre', 'Alimentacion', 'Gastronomia Artesanal', 'Panaderia', 'internal', 'kg', 'Pan artesanal de masa madre. Fermentacion natural 24h, horneado en horno artesanal. Lote: 600g harina + 400g agua -> 1 hogaza 800g. Energia lote: 15.4 MJ. Por kg: 19.3 MJ/kg = 5.4 kWh/kg. Precio: 5 TQ/kg. Fuente: LCA pan artesanal. Documentado en Feria Conuquera (Flor de Tilo).', 'Hecho en Casa', '', '', 5, 0, 'kg', 0, 2, 1, 2, 0, true, true, false);
