  ('__NODE__', 'Torta de Platano Artesanal', 'Alimentacion', 'Gastronomia Artesanal', 'Postres', 'internal', 'porcion', 'Torta de platano artesanal. Lote: 500g platano + 100g papelon -> 4 porciones de ~150g. Energia lote: 5.5 MJ. Por kg: 9.2 MJ/kg = 2.6 kWh/kg. Por porcion (150g): 1 TQ. Fuente: Prensa Rural. Documentado en Feria Conuquera.', 'Hecho en Casa', '', '', 1, 0, 'kg', 0, 1, 1, 1, 0, true, true, false);
